#include <stdio.h>
#include <string.h>



int main(void) {
    char source[102], target[102];
    if (!fgets(source, sizeof(source), stdin)) source[0] = '\0';
    source[strcspn(source, "\n")] = '\0';
    int i = 0;
    do { target[i] = source[i]; } while (source[i++]);
    puts(target);
    return 0;
}
